<script setup lang="ts">
import {computed,ref} from 'vue';
import ModalSheet from './ModalSheet.vue';
const props=defineProps<{label:string;modelValue:string;options:{value:string;label:string;meta?:string}[];disabled?:boolean}>();
const emit=defineEmits<{ 'update:modelValue':[value:string] }>();
const opened=ref(false),query=ref(''),trigger=ref<HTMLButtonElement|null>(null);
const selected=computed(()=>props.options.find(o=>o.value===props.modelValue));
const list=computed(()=>props.options.filter(o=>!query.value||(o.label+' '+(o.meta||'')).toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
function close(){opened.value=false;}
function open(){if(props.disabled)return;query.value='';opened.value=true;}
function choose(value:string){emit('update:modelValue',value);close();}
</script>
<template><div class="attribute-select"><button ref="trigger" type="button" class="attribute-trigger" :class="{selected:!!modelValue}" :disabled="disabled" :aria-label="label+'：'+(selected?.label||'全部')" aria-haspopup="dialog" :aria-expanded="opened" @click="open"><span>{{label}}<template v-if="selected">：{{selected.label}}</template></span><i aria-hidden="true">⌄</i></button>
<Teleport to="body"><ModalSheet v-if="opened" :title="label" modal-class="attribute-menu-sheet" @close="close"><input v-if="options.length>8" v-model="query" class="attribute-option-search" :aria-label="'查找'+label+'选项'" placeholder="查找选项"><div class="attribute-options" role="listbox" :aria-label="label"><button role="option" :aria-selected="!modelValue" @click="choose('')">全部<span v-if="!modelValue">✓</span></button><button v-for="option in list" :key="option.value" role="option" :aria-selected="modelValue===option.value" @click="choose(option.value)"><span class="option-name">{{option.label}}</span><i v-if="modelValue===option.value">✓</i><small v-if="option.meta" class="option-meta">{{option.meta}}</small></button><p v-if="!list.length">没有匹配选项</p></div></ModalSheet></Teleport></div></template>
<style scoped>
.attribute-select{flex:none;display:flex;align-items:center;min-height:48px;max-width:220px}.attribute-trigger{display:flex;align-items:center;gap:6px;position:relative;min-height:48px;border:0;border-radius:8px;background:transparent;isolation:isolate;color:var(--ink);padding:6px 10px;font-size:14px;max-width:100%}.attribute-trigger::before{content:'';position:absolute;inset:6px 0;border:1px solid var(--line-soft);border-radius:8px;background:var(--paper);z-index:-1}.attribute-trigger span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.attribute-trigger i{font-style:normal;flex:none}.attribute-trigger.selected{color:var(--accent-dark)}.attribute-trigger.selected::before{border-color:var(--accent);background:var(--accent-soft)}:global(.attribute-menu-sheet){height:min(560px,80dvh)!important;max-height:80dvh!important}:global(.attribute-menu-sheet .modal-body){display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden!important}.attribute-option-search{width:100%;font-size:16px;min-height:40px;flex:none;padding:8px 12px;border:1px solid var(--line);border-radius:8px;margin-bottom:8px}.attribute-options{flex:1;overflow-y:auto;overflow-x:hidden;overscroll-behavior-y:contain;min-height:0;-webkit-overflow-scrolling:touch;touch-action:pan-y}.attribute-options>button{display:flex;gap:12px;justify-content:space-between;align-items:center;width:100%;min-height:48px;padding:10px 4px;border:0;border-bottom:1px solid var(--line-soft);background:var(--paper);color:var(--ink);text-align:left;font-size:16px}.attribute-options button[aria-selected=true]{color:var(--accent-dark);font-weight:600}.attribute-options span{overflow-wrap:anywhere;min-width:0}.attribute-options .option-name{flex:1}.attribute-options .option-meta{flex:none;color:var(--muted);font-size:12px;font-weight:400;white-space:nowrap}.attribute-options button:active{background:var(--accent-soft)}.attribute-options i{font-style:normal;flex:none}.attribute-options p{font-size:14px;color:var(--muted);padding:16px 0}
</style>
